  // The fixture goes into the runtime's own storage before the provider
  // mounts; the runtime then loads it like any persisted session.
  const [seeded, setSeeded] = useState(false);
  useEffect(() => {
    if (options.seedScene) {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(rathausBarmenMeasurements));
    }
    setSeeded(true);
  }, [options.seedScene]);
  const {
    map,
    setContainer
  } = useStoryMap(options.surfaceTiles);
  const meshStatus = useStoryMesh(map);
  return <div style={{
    position: "relative",
    width: "100vw",
    height: "100vh"
  }}>
      <div ref={setContainer} style={{
      position: "absolute",
      inset: 0
    }} />
      {map && seeded ? <MeasurementRuntime map={map} showAllTools={options.showAllTools} /> : null}
      <div style={{
      position: "absolute",
      left: 12,
      bottom: 12,
      padding: "3px 6px",
      font: "12px/1.45 system-ui, sans-serif",
      background: "#fff"
    }}>
        {meshStatus}
      </div>
    </div>;
